// saboro 管理者画面：利用者の一覧、売上・費用・利益、AI の使用状況。データは /api/admin/*（Worker の秘密 ADMIN_TOKEN で認証）
// 秘密はこのタブの間だけ保存する（sessionStorage。タブを閉じると消える）
'use strict';
const KEY='saboro-admin-token',app=document.getElementById('app');
const PLAN={api:'saboro の API',byo:'本人の AI',free:'無料'},STATUS={active:'利用中',trial:'お試し',stopped:'停止'};
let token=null,data=null,month=null,editing=null,paying=null;
try{token=sessionStorage.getItem(KEY)}catch{}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const yen=v=>v==null?'—':`${(Math.round(v)||0).toLocaleString('ja-JP')}円`,num=v=>Math.round(v||0).toLocaleString('ja-JP');
const panel=(title,body,tools='')=>`<section class="panel"><h2 class="panel-heading"><span class="mark" aria-hidden="true"></span>${title}${tools?`<span class="tools">${tools}</span>`:''}</h2><div class="panel-body">${body}</div></section>`;
const short=id=>id==='legacy'?'最初の利用者':String(id).slice(0,8);
const nameOf=u=>u?esc(u.label||short(u.account)):'（削除済み）';
// 最終接続などの日時：何分前・何時間前・何日前
function ago(iso){if(!iso)return '—';const s=(Date.now()-new Date(iso))/1000;if(!(s>=0))return esc(iso.slice(0,10));if(s<120)return '今';if(s<3600)return `${Math.floor(s/60)}分前`;if(s<86400)return `${Math.floor(s/3600)}時間前`;return `${Math.floor(s/86400)}日前`}
function toast(s){const e=document.getElementById('toast');e.textContent=s;e.style.display='block';e.onclick=()=>{e.style.display='none'};clearTimeout(toast.t);toast.t=setTimeout(()=>{e.style.display='none'},3000)}
async function api(path,body){const r=await fetch('/api/admin'+path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+token,...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});if(r.status===401){logout('管理者の秘密が違います。');throw Error('unauthorized')}if(r.status===503){app.innerHTML=notConfigured();throw Error('not_configured')}if(!r.ok)throw Error(r.status===400?'入力を確認してください':`エラー（${r.status}）`);return r.json()}
function notConfigured(){return panel('管理者画面の準備',`<p>サーバーに管理者の秘密（<code>ADMIN_TOKEN</code>）がまだ設定されていません。32 文字以上のランダムな文字列を用意して、次のどちらかで設定してください。</p><ol><li>GitHub のリポジトリの Settings → Secrets and variables → Actions に <code>ADMIN_TOKEN</code> として追加し、次の公開（main への反映）を待つ</li><li>手元で <code>npx wrangler secret put ADMIN_TOKEN</code> を実行する</li></ol><p class="muted">設定後にこのページを開き直し、同じ文字列でログインします。</p>`)}
function login(error=''){app.innerHTML=panel('管理者ログイン',`<form id="login"><div class="form-grid"><div class="wide"><label for="token">管理者の秘密（ADMIN_TOKEN）</label><input class="form-control" type="password" id="token" autocomplete="current-password" required></div></div>${error?`<p class="err">${esc(error)}</p>`:''}<div class="actions"><button class="btn btn-primary">ログイン</button><span class="muted">このタブを閉じると、ログインは解除されます。</span></div></form>`);document.getElementById('token').focus()}
function logout(message=''){token=null;try{sessionStorage.removeItem(KEY)}catch{}login(message)}
async function load(m=month){try{data=await api('/overview'+(m?`?month=${encodeURIComponent(m)}`:''));month=data.month;render()}catch(e){if(!['unauthorized','not_configured'].includes(e.message))app.innerHTML=panel('読み込めません',`<p class="err">${esc(e.message)}</p><button class="btn" data-action="reload">再読み込み</button>`)}}
// 概要：売上・利益・見込み・未入金
function summary(){const s=data.summary,set=data.settings;const stat=(label,value,sub='',minus=false)=>`<div class="stat${minus?' minus':''}"><span class="stat-label">${label}</span><span class="stat-num">${value}${sub?`<small>${sub}</small>`:''}</span></div>`;
 const stats=`<div class="stats">${stat('売上（入金）',yen(s.revenue),`${s.paying}人`)}${stat('利益',yen(s.profit),'',s.profit<0)}${stat('1人あたり利益',yen(s.perPaying),'',s.perPaying<0)}${stat('見込み（月額の合計）',yen(s.expected))}${stat('未入金',`${s.unpaid.length}人`)}</div>`;
 const row=(k,v,note='')=>`<tr><th>${k}</th><td class="num${v<0?' minus':''}">${yen(v)}</td><td class="muted">${note}</td></tr>`;
 const table=`<div class="scroll"><table class="table-default"><tbody>${row('売上（入金の合計）',s.revenue)}${row('決済手数料',-s.fees,`売上の ${(set.feeRate*100).toFixed(1)}%`)}${row('消費税',-s.tax,set.taxable?'税込の売上の 10/110':'引かない（免税事業者の設定）')}${row('AI の費用（目安）',-s.apiCost,`「saboro の API」プランの人の使用量 $${s.apiUsd.toFixed(2)} × ${set.usdJpy}円。通常料金での目安（Batch なら約半分）`)}${row('固定費',-s.fixed,'この月に含まれる費用の合計')}${row('<strong>利益</strong>',s.profit,s.paying?`入金のあった ${s.paying}人で割ると ${yen(s.perPaying)}`:'')}</tbody></table></div>`;
 const unpaid=s.unpaid.length?`<p class="muted" style="margin-top:8px">未入金（利用中・月額あり）：${s.unpaid.map(id=>nameOf(data.users.find(u=>u.account===id))).join('、')}</p>`:'';
 return panel(`${esc(month)} の売上と利益`,stats+table+unpaid)}
function trend(){const rows=data.trend.map(t=>`<tr${t.month===month?' style="font-weight:700"':''}><td>${esc(t.month)}</td><td class="num">${yen(t.revenue)}</td><td class="num">${yen(t.fees+t.tax)}</td><td class="num">${yen(t.apiCost)}</td><td class="num">${yen(t.fixed)}</td><td class="num${t.profit<0?' minus':''}">${yen(t.profit)}</td><td class="num">${t.paying}人</td></tr>`).join('');
 return panel('推移（6 か月）',`<div class="scroll"><table class="table-default wide"><thead><tr><th>月</th><th class="num">売上</th><th class="num">手数料・税</th><th class="num">AI の費用</th><th class="num">固定費</th><th class="num">利益</th><th class="num">入金</th></tr></thead><tbody>${rows}</tbody></table></div><p class="muted" style="margin-top:6px">AI の費用は、利用者の端末が残す使用量（直近 3 か月分）から計算するため、それより前の月は 0 円になります。</p>`)}
// 利用者の一覧と、編集・入金の記録
function users(){const paid=new Set(data.payments.map(p=>p.account)),unpaid=new Set(data.summary.unpaid);
 const rows=data.users.map(u=>{const m=u.usageMonth,est=m?.estimateUsd?m.estimateUsd*data.settings.usdJpy:0;return `<tr><td><strong>${nameOf(u)}</strong><br><span class="muted"><code>${esc(short(u.account))}</code>${u.created?` ・登録 ${esc(u.created.slice(0,10))}`:''}</span>${u.note?`<br><span class="muted">${esc(u.note)}</span>`:''}</td>
  <td><span class="tag ${esc(u.status)}">${STATUS[u.status]}</span><br><span class="muted">${PLAN[u.plan]}</span></td><td class="num">${u.price?yen(u.price):'—'}<br>${paid.has(u.account)?'<span class="tag active">入金済み</span>':unpaid.has(u.account)?'<span class="tag unpaid">未入金</span>':''}</td>
  <td>${ago(u.seen)}<br><span class="muted">${esc({darwin:'Mac',win32:'Windows'}[u.os]||u.os||'—')}${u.version?` ・${esc(String(u.version).slice(0,10))}`:''}</span></td><td>同期 ${ago(u.lastSync)}<br><span class="muted">授業 ${u.courses}・課題 ${u.tasks}${u.creds?'':'・<span class="err">manabo 未設定</span>'}</span>${u.lastError?`<br><span class="err" title="${esc(u.lastError)}">エラーあり</span>`:''}</td>
  <td class="num">${m?`${num(m.calls)}回${m.failed?`<br><span class="muted">失敗 ${num(m.failed)}</span>`:''}`:'—'}<br><span class="muted">${m?`目安 ${yen(est)}`:''}</span></td>
  <td><button class="btn btn-sm" data-action="edit" data-account="${esc(u.account)}">編集</button> <button class="btn btn-sm" data-action="pay" data-account="${esc(u.account)}">入金を記録</button></td></tr>`}).join('');
 return panel(`利用者（${data.users.length}人）`,`${editForm()}${payForm()}${data.users.length?`<div class="scroll"><table class="table-default wide"><thead><tr><th>利用者</th><th>状態・プラン</th><th class="num">月額</th><th>最終接続・端末</th><th>同期・件数</th><th class="num">今月の AI</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p class="muted">まだ登録した利用者はいません。デスクトップアプリで接続すると、ここに出ます。</p>'}<p class="muted" style="margin-top:6px">授業名・課題・資料の中身は、この画面には出しません（件数だけ）。</p>`)}
function editForm(){const u=data.users.find(x=>x.account===editing);if(!u)return '';const opt=(map,v)=>Object.entries(map).map(([k,l])=>`<option value="${k}"${k===v?' selected':''}>${l}</option>`).join('');
 return `<form class="editbox" id="edit-form"><strong>${nameOf(u)} を編集</strong><div class="form-grid"><div><label for="e-label">呼び名</label><input class="form-control" id="e-label" maxlength="40" value="${esc(u.label)}"></div><div><label for="e-status">状態</label><select class="form-control" id="e-status">${opt(STATUS,u.status)}</select></div><div><label for="e-plan">プラン</label><select class="form-control" id="e-plan">${opt(PLAN,u.plan)}</select></div><div><label for="e-price">月額（税込・円）</label><input class="form-control" id="e-price" type="number" min="0" step="1" value="${u.price}"></div><div><label for="e-started">利用開始日</label><input class="form-control" id="e-started" type="date" value="${esc(u.started)}"></div><div class="wide"><label for="e-note">メモ</label><input class="form-control" id="e-note" maxlength="500" value="${esc(u.note)}"></div></div><div class="actions" style="margin-top:0"><button class="btn btn-primary">保存</button><button class="btn" type="button" data-action="cancel">やめる</button></div></form>`}
function payForm(){const u=data.users.find(x=>x.account===paying);if(!u)return '';const today=new Date().toISOString().slice(0,10);
 return `<form class="editbox" id="pay-form"><strong>${nameOf(u)} の入金を記録</strong><div class="form-grid"><div><label for="p-month">対象の月</label><input class="form-control" id="p-month" type="month" value="${esc(month)}" required></div><div><label for="p-amount">金額（税込・円。返金はマイナス）</label><input class="form-control" id="p-amount" type="number" step="1" value="${u.price||''}" required></div><div><label for="p-paid">入金日</label><input class="form-control" id="p-paid" type="date" value="${today}"></div><div><label for="p-method">方法</label><input class="form-control" id="p-method" maxlength="20" placeholder="振込・PayPay など"></div><div class="wide"><label for="p-note">メモ</label><input class="form-control" id="p-note" maxlength="200"></div></div><div class="actions" style="margin-top:0"><button class="btn btn-primary">記録</button><button class="btn" type="button" data-action="cancel">やめる</button></div></form>`}
function payments(){const rows=data.payments.map(p=>`<tr><td>${esc(p.paid_on||p.created.slice(0,10))}</td><td>${nameOf(data.users.find(u=>u.account===p.account))}</td><td class="num${p.amount<0?' minus':''}">${yen(p.amount)}</td><td>${esc(p.method)}</td><td class="muted">${esc(p.note)}</td><td><button class="btn btn-sm" data-action="delpay" data-id="${esc(p.id)}">削除</button></td></tr>`).join('');
 return panel(`${esc(month)} の入金`,data.payments.length?`<div class="scroll"><table class="table-default wide"><thead><tr><th>入金日</th><th>利用者</th><th class="num">金額</th><th>方法</th><th>メモ</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p class="muted">この月の入金の記録はありません。利用者の「入金を記録」から追加します。</p>')}
// 費用：その月だけのもの・毎月のもの
function costs(){const rows=data.costs.map(c=>`<tr${c.applies?'':' class="muted"'}><td>${esc(c.item)}${c.note?`<br><span class="muted">${esc(c.note)}</span>`:''}</td><td class="num">${yen(c.amount)}</td><td>${c.recurring?`毎月（${esc(c.month)}〜${c.end_month?esc(c.end_month):''}）`:esc(c.month)}</td><td>${c.applies?'含む':'—'}</td><td>${c.recurring&&!c.end_month?`<button class="btn btn-sm" data-action="endcost" data-id="${esc(c.id)}">${esc(month)} で終了</button> `:''}<button class="btn btn-sm" data-action="delcost" data-id="${esc(c.id)}">削除</button></td></tr>`).join('');
 return panel('費用',`${data.costs.length?`<div class="scroll"><table class="table-default wide"><thead><tr><th>項目</th><th class="num">金額</th><th>期間</th><th>${esc(month)}</th><th></th></tr></thead><tbody>${rows}</tbody></table></div>`:'<p class="muted">登録した費用はありません。</p>'}
 <form id="cost-form" class="editbox" style="margin-top:12px"><strong>費用を追加</strong><div class="form-grid"><div><label for="c-item">項目</label><input class="form-control" id="c-item" maxlength="40" required placeholder="Cloudflare・Apple など"></div><div><label for="c-amount">金額（円・月あたり）</label><input class="form-control" id="c-amount" type="number" min="0" step="1" required></div><div><label for="c-month">月（毎月なら開始月）</label><input class="form-control" id="c-month" type="month" value="${esc(month)}" required></div><div><label class="check" style="font-size:14px;color:inherit"><input type="checkbox" id="c-recurring" checked> 毎月かかる</label></div><div class="wide"><label for="c-note">メモ</label><input class="form-control" id="c-note" maxlength="200" placeholder="年額のものは 12 で割って毎月に（例：Apple 年 99 ドル → 約 1,240 円）"></div></div><div class="actions" style="margin-top:0"><button class="btn btn-primary">追加</button></div></form>
 <p class="muted">「削除」は記録ごと消します（過去の月の利益も変わります）。やめた毎月の費用は「終了」にすると、それまでの月は残ります。</p>`)}
function usage(){const u=data.summary.usage,s=data.summary.users,est=u.estimateUsd*data.settings.usdJpy,prov=Object.entries(u.byProvider).map(([k,v])=>`${esc(k)} ${num(v.calls)}回${v.failed?`（失敗 ${num(v.failed)}）`:''}`).join('・');
 return panel(`${esc(month)} の使用状況`,`<div class="scroll"><table class="table-default"><tbody>
 <tr><th>利用者</th><td>${s.total}人（利用中 ${s.active}・お試し ${s.trial}・停止 ${s.stopped}）</td></tr><tr><th>接続中の端末</th><td>24 時間以内 ${s.seen24h}台・7 日以内 ${s.seen7d}台</td></tr>
 <tr><th>AI を使った回数</th><td>${num(u.calls)}回${u.failed?`（うち失敗 ${num(u.failed)}回）`:''}${prov?`<br><span class="muted">${prov}</span>`:''}</td></tr>
 <tr><th>トークン</th><td>${u.tokenCalls?`入力 ${num(u.input)}・出力 ${num(u.output)}（Claude の ${num(u.tokenCalls)}回分、1回平均 入力 ${num(u.input/u.tokenCalls)}・出力 ${num(u.output/u.tokenCalls)}）`:'—'}</td></tr>
 <tr><th>全員分をこちらの API で作った場合</th><td>通常 ${yen(est)}・Batch ${yen(est/2)}（$${u.estimateUsd.toFixed(2)}）${u.tokenCalls?`／1回平均 ${yen(est/u.tokenCalls)}`:''}</td></tr></tbody></table></div><p class="muted" style="margin-top:6px">各端末が記録した使用量（1.0.26 以降）の合計です。Codex はトークン数が分からないため、回数だけです。</p>`)}
function settings(){const s=data.settings;return panel('計算の設定',`<form id="settings-form"><div class="form-grid"><div><label for="s-fee">決済手数料（%）</label><input class="form-control" id="s-fee" type="number" min="0" max="20" step="0.1" value="${(s.feeRate*100).toFixed(1)}"></div><div><label for="s-usd">1 ドル（円）</label><input class="form-control" id="s-usd" type="number" min="50" max="500" step="1" value="${s.usdJpy}"></div><div><label class="check" style="font-size:14px;color:inherit"><input type="checkbox" id="s-tax"${s.taxable?' checked':''}> 消費税を売上から引く（課税事業者）</label></div></div><div class="actions" style="margin-top:0"><button class="btn btn-primary">保存</button></div></form>`)}
function render(){app.innerHTML=`<div class="bar"><label for="month" class="muted">月</label><input class="form-control" type="month" id="month" value="${esc(month)}"><button class="btn btn-sm" data-action="thismonth"${month===data.current?' disabled':''}>今月</button><button class="btn btn-sm" data-action="reload">再読み込み</button><span class="grow"></span><button class="btn btn-sm" data-action="logout">ログアウト</button></div>${summary()}${users()}${payments()}${costs()}${usage()}${trend()}${settings()}`}
const val=id=>document.getElementById(id)?.value??'';
async function act(fn,message){try{await fn();editing=paying=null;toast(message);await load()}catch(e){if(!['unauthorized','not_configured'].includes(e.message))toast(e.message)}}
app.addEventListener('submit',e=>{e.preventDefault();const id=e.target.id;
 if(id==='login'){token=val('token').trim();try{sessionStorage.setItem(KEY,token)}catch{}load();return}
 if(id==='edit-form')act(()=>api('/user',{account:editing,label:val('e-label'),status:val('e-status'),plan:val('e-plan'),price:Number(val('e-price')||0),started:val('e-started'),note:val('e-note')}),'保存しました');
 if(id==='pay-form')act(()=>api('/payment',{account:paying,month:val('p-month'),amount:Number(val('p-amount')),paid_on:val('p-paid'),method:val('p-method'),note:val('p-note')}),'入金を記録しました');
 if(id==='cost-form')act(()=>api('/cost',{item:val('c-item'),amount:Number(val('c-amount')),month:val('c-month'),recurring:document.getElementById('c-recurring').checked,note:val('c-note')}),'費用を追加しました');
 if(id==='settings-form')act(()=>api('/settings',{feeRate:Number(val('s-fee'))/100,usdJpy:Number(val('s-usd')),taxable:document.getElementById('s-tax').checked}),'設定を保存しました')});
app.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;
 if(a==='reload')load();else if(a==='logout')logout();else if(a==='thismonth')load(data.current);
 else if(a==='edit'){editing=b.dataset.account;paying=null;render();document.getElementById('e-label')?.focus()}
 else if(a==='pay'){paying=b.dataset.account;editing=null;render();document.getElementById('p-amount')?.focus()}
 else if(a==='cancel'){editing=paying=null;render()}
 else if(a==='delpay'&&confirm('この入金の記録を削除しますか？'))act(()=>api('/payment/delete',{id:b.dataset.id}),'削除しました');
 else if(a==='delcost'&&confirm('この費用を削除しますか？過去の月の利益も変わります。'))act(()=>api('/cost/delete',{id:b.dataset.id}),'削除しました');
 else if(a==='endcost'&&confirm(`${month} を最後の月として終了しますか？`))act(()=>api('/cost/end',{id:b.dataset.id,month}),'終了にしました')});
app.addEventListener('change',e=>{if(e.target.id==='month'&&e.target.value)load(e.target.value)});
if(token)load();else login();
